export function mergeRouters<TRouters extends AnyRouter[]>(
  ...routerList: [...TRouters]
): MergeRouters<TRouters> {
  const mergedRouter: any = {};

  for (const router of routerList) {
    for (const [key, procedure] of Object.entries(router._def.procedures)) {
      if (mergedRouter[key]) {
        throw new Error(`Duplicate key: ${key}`);
      }
      mergedRouter[key] = procedure;
    }
  }

  const _def: AnyRouterDef = {
    _config: routerList[0]._def._config,
    router: true,
    procedures: mergedRouter,
    ...emptyRouter,
    queries: Object.entries(mergedRouter)
      .filter((pair) => (pair[1] as any)._def.query)
      .reduce((acc, [key, val]) => ({ ...acc, [key]: val }), {}),
    mutations: Object.entries(mergedRouter)
      .filter((pair) => (pair[1] as any)._def.mutation)
      .reduce((acc, [key, val]) => ({ ...acc, [key]: val }), {}),
    subscriptions: Object.entries(mergedRouter)
      .filter((pair) => (pair[1] as any)._def.subscription)
      .reduce((acc, [key, val]) => ({ ...acc, [key]: val }), {}),
  };

  const router: AnyRouter = {
    ...mergedRouter,
    _def,
    createCaller(ctx: TRouters[number]['_def']['_config']['$types']['ctx']) {
      return createCallerFactory<TRouters[number]['_def']['_config']>()(router as any)(ctx);
    },
    getErrorShape(opts) {
      const { path, error } = opts;
      const { code } = opts.error;
      const shape: DefaultErrorShape = {
        message: error.message,
        code: TRPC_ERROR_CODES_BY_KEY[code],
        data: {
          code,
          httpStatus: getHTTPStatusCodeFromError(error),
        },
      };
      if (routerList[0]._def._config.isDev && typeof opts.error.stack === 'string') {
        shape.data.stack = opts.error.stack;
      }
      if (typeof path === 'string') {
        shape.data.path = path;
      }
      return this._def._config.errorFormatter({ ...opts, shape });
    },
  };

  return router as any;
}
